        self.base = None
        self.changes = []


def is_fm_indicator(text):
    return len(text) == 8 and text.startswith("FM") and is_digits(text[2:], 6, 6)


def is_change_indicator(text):
    return text in CHANGE_INDICATORS or is_fm_indicator(text)


def is_period(text):
    return len(text) == 9 and text[4] == "/" and is_digits(text[:4], 4, 4) and is_digits(text[5:], 4, 4)


def parse_period(text, issue_day, calendar):
    if not is_period(text):
        return None
    start_hour, end_hour = int(text[2:4]), int(text[7:9])
    if start_hour > 23 or not 1 <= end_hour <= 24:
        return None
    start = calendar.forecast_time(int(text[:2]), start_hour, 0, issue_day)
    end = calendar.forecast_time(int(text[5:7]), end_hour, 0, issue_day)
    if start is None or end is None or start >= end:
        return None
    return start, end


def fm_time(text, issue_day, calendar):
    hour, minute = int(text[4:6]), int(text[6:8])
    if hour > 23 or minute > 59:
        return None
    return calendar.forecast_time(int(text[2:4]), hour, minute, issue_day)


def change_period(forecast, groups, index, calendar, errors):
    position, kind = groups[index]
    index += 1
    if kind in PROBABILITIES and index < len(groups) and groups[index][1] == "TEMPO":
        kind += " TEMPO"
        index += 1
    issue_day = day_of(forecast.issue)
    if is_fm_indicator(kind):
        time = fm_time(kind, issue_day, calendar)
        if time is None or not forecast.start <= time < forecast.end:
            errors.append((position, f'invalid period "{kind}"'))
            return None, index
        return Change("FM", time, None, []), index
    if index == len(groups) or not is_period(groups[index][1]):
        errors.append((position, f'missing period "{kind}"'))
        return None, index
    period_position, period_text = groups[index]
    period = parse_period(period_text, issue_day, calendar)
    if period is None or period[0] < forecast.start or period[1] > forecast.end:
        errors.append((period_position, f'invalid period "{period_text}"'))
        return None, index + 1
    return Change(kind, period[0], period[1], []), index + 1


def split_changes(forecast, groups, calendar, errors):
    index = 0
    while index < len(groups) and not is_change_indicator(groups[index][1]):
        index += 1
    base = groups[:index]
    changes = []
    while index < len(groups):
        change, index = change_period(forecast, groups, index, calendar, errors)
        end = index
        while end < len(groups) and not is_change_indicator(groups[end][1]):
            end += 1
        if change is not None:
            change.groups = groups[index:end]
            changes.append(change)
        index = end
    return base, changes


def overlay(state, change):
    return State(
        state.wind if change.wind is None else change.wind,
        state.visibility if change.visibility is None else change.visibility,
        state.weather if change.weather is None else change.weather,
        state.cloud if change.cloud is None else change.cloud,
    )


def prevailing_state(forecast, hour):
    state = forecast.base
    for change in forecast.changes:
        if change.kind == "FM" and change.start <= hour:
            state = change.state
        elif change.kind == "BECMG" and change.end <= hour:
            state = overlay(state, change.state)
    return state


def temporary_states(forecast, hour):
    prevailing = prevailing_state(forecast, hour)
    states = []
    for change in forecast.changes:
        if change.kind in TEMPORARY_KINDS and change.start <= hour < change.end:
            states.append((change.kind, overlay(prevailing, change.state)))
    return states

from math import gcd


SINE_TABLE = (0, 174, 342, 500, 643, 766, 866, 940, 985, 1000)
LONG_MONTHS = (1, 3, 5, 7, 8, 10, 12)
MINUTES_PER_DAY = 1440
MILLIMETERS_PER_MILE = 1609344


def sin(angle):
    angle %= 360
    if angle <= 90:
        return SINE_TABLE[angle // 10]
    if angle <= 180:
        return SINE_TABLE[(180 - angle) // 10]
    if angle <= 270:
        return -SINE_TABLE[(angle - 180) // 10]
    return -SINE_TABLE[(360 - angle) // 10]


def cos(angle):
    return sin(angle + 90)


def knots(speed, unit):
    if unit == "MPS":
        return (speed * 1944 + 500) // 1000
    return speed


def inhg_from_hpa(hpa):
    return (hpa * 2953 + 500) // 1000


def hpa_from_inhg(inhg):
    return (inhg * 33864 + 50000) // 100000


def days_in_month(year, month):
    if month == 2:
        leap = year % 4 == 0 and year % 100 != 0 or year % 400 == 0
        return 29 if leap else 28
    return 31 if month in LONG_MONTHS else 30


def following_month(year, month):
    if month == 12:
        return year + 1, 1
    return year, month + 1


def day_minutes(day, hour, minute):
    return ((day - 1) * 24 + hour) * 60 + minute


def day_of(time):
    return time // MINUTES_PER_DAY + 1


def hour_mark(time):
    return time - time % 60


class Calendar:
    def __init__(self, year, month):
        self.year = year
        self.month = month
        self.days = days_in_month(year, month)
        self.next_year, self.next_month = following_month(year, month)
        self.next_days = days_in_month(self.next_year, self.next_month)

    def forecast_time(self, day, hour, minute, issue_day):
        if day >= issue_day:
            if day > self.days:
                return None
            return day_minutes(day, hour, minute)
        if day < 1 or day > self.next_days:
            return None
        return self.days * MINUTES_PER_DAY + day_minutes(day, hour, minute)

    def stamp(self, time):
        year, month = self.year, self.month
        if time >= self.days * MINUTES_PER_DAY:
            year, month = self.next_year, self.next_month
            time -= self.days * MINUTES_PER_DAY
        day, minutes = divmod(time, MINUTES_PER_DAY)
        return f"{year:04d}-{month:02d}-{day + 1:02d}T{minutes // 60:02d}:{minutes % 60:02d}Z"


def miles_from_meters(meters):
    return 1000 * meters, MILLIMETERS_PER_MILE


def mile_fraction(whole, numerator, denominator):
    if denominator == 0:
        return whole, 1
    return whole * denominator + numerator, denominator


def meters_from_miles(numerator, denominator):
    return MILLIMETERS_PER_MILE * numerator // (1000 * denominator)


def fraction_less(first, second):
    return first[0] * second[1] < second[0] * first[1]


def fraction_text(numerator, denominator):
    if denominator == 0:
        return "undefined"
    divisor = gcd(numerator, denominator)
    return f"{numerator // divisor}/{denominator // divisor}"

from units import hour_mark


CATEGORIES = ("VFR", "MVFR", "IFR", "LIFR")


def covers(forecast, time):
    hour = hour_mark(time)
    return forecast.issue <= time and forecast.start <= hour < forecast.end


def chosen_forecast(forecasts, time):
    chosen = None
    for forecast in forecasts:
        if covers(forecast, time) and (chosen is None or forecast.issue >= chosen.issue):
            chosen = forecast
    return chosen


class Contingency:
    def __init__(self):
        self.table = [[0] * len(CATEGORIES) for _ in CATEGORIES]
        self.temporary_hits = 0

    def add(self, forecast, observed, temporary_hit):
        self.table[CATEGORIES.index(forecast)][CATEGORIES.index(observed)] += 1
        if temporary_hit:
            self.temporary_hits += 1

    def row_total(self, row):
        return sum(self.table[row])

    def column_total(self, column):
        return sum(row[column] for row in self.table)

    def total(self):
        return sum(sum(row) for row in self.table)

    def hits(self):
        return sum(self.table[index][index] for index in range(len(CATEGORIES))), self.total()

    def hits_with_temporary(self):
        return self.temporary_hits, self.total()

    def skill_score(self):
        hits, total = self.hits()
        expected = sum(
            self.row_total(index) * self.column_total(index) for index in range(len(CATEGORIES))
        )
        return total * hits - expected, total * total - expected

    def detection(self, index):
        return self.table[index][index], self.column_total(index)

    def false_alarm(self, index):
        row_total = self.row_total(index)
        return row_total - self.table[index][index], row_total
